    def observe(
        self,
        wallet_id: str,
        operation_id: object,
        body: object,
    ) -> tuple[int, dict]:
        """多源观察上报。返回 (HTTP 状态码, ``{"state": ...}``)。

        body 恰为 ``{source, report}``（键集由 HTTP 边界校验）：source 为
        安全 ID，report 为达门槛链上报告 B（chain_report 同形五字段）。

        - 各源首收 201；同源同体 200；改报、未知/停用源、终态后新增票
          一律 409 且不改变现场；异体票并存为 conflict；
        - 达 quorum 时决定性 adopted 票、chain_report(B) 与资产提交在
          锁内一次原子提交；启用仲裁后该 pending 操作的 chain report
          一律 409；
        - 仲裁仅由 chain_vote/chain_report/asset_operation_committed
          审计事件持久化，重放（同源同体）不记事件。恢复检查、存在性、
          校验、状态判定与事件追加全部在每钱包跨进程事务锁内完成。"""
        try:
            with self._wallet_lock(wallet_id):
                self._heal_wallet(wallet_id)
                # 404 优先于 400：存在性在锁内、heal 之后先判定
                self._get_wallet_or_404(wallet_id)
                self._assert_wallet_active_locked(wallet_id)
                # 持锁访问先重放策略、票、操作与相邻提交事件：账本文件
                # 缺失时 heal 未覆盖的矛盾现场也在此 fail-closed（503），
                # 优先于任何参数 400/404 判定，绝不据锁外快照继续。
                self._reconcile_chain_state_locked(wallet_id)
                self._validate_operation_id(operation_id)
                if not isinstance(body, dict) or set(body) != {
                    "source",
                    "report",
                }:
                    raise ServiceError(
                        400, "body must contain exactly source and report"
                    )
                source = body["source"]
                if not isinstance(source, str) or not ROTATION_ID_RE.match(
                    source
                ):

    def _get_arb(self, wallet="w1", asset="btc"):
        return self.srv.request(
            "GET", f"/v1/wallets/{wallet}/chain/{asset}/arbitration"
        )

    def _create_op(self, operation_id="op1", asset_id="btc", delta=100):
        status, body = self.srv.request(
            "POST",
            "/v1/wallets/w1/asset-operations",
            {
                "operation_id": operation_id,
                "asset_id": asset_id,
                "delta": delta,
            },
        )
        self.assertEqual(status, 201)
        return body

    def _observe(self, source, report, wallet="w1", operation="op1"):
        return self.srv.request(
            "POST",
            f"/v1/wallets/{wallet}/chain/{operation}/observe",
            {"source": source, "report": report},
        )

    def _events(self, wallet="w1"):
        status, body = self.srv.request(
            "GET", f"/v1/wallets/{wallet}/audit-events"
        )
        self.assertEqual(status, 200)
        return body["events"]


class ArbitrationPolicyHttpTest(_HttpBase):
    """PUT/GET .../chain/{asset}/arbitration 的校验与幂等。"""

